// Calculate current month key and deadline
const now = new Date();
const year = now.getFullYear();
const month = now.getMonth();
const monthKey = `${year}-${String(month+1).padStart(2,'0')}`;

// Calculate second Thursday (deadline)
const first = new Date(year, month, 1);
const firstDay = first.getDay();
const firstThursday = 1 + ((4 - firstDay + 7) % 7);
const deadlineDay = firstThursday + 7;
const deadlineDate = new Date(year, month, deadlineDay, 14, 0, 0);

// Stop after deadline
if (now > deadlineDate) {
  return []; // empty = stop execution
}

const dayNames = ['일','월','화','수','목','금','토'];
const deadlineStr = `${month+1}월 ${deadlineDay}일(${dayNames[deadlineDate.getDay()]}) 오후 2시`;

return [{
  json: {
    monthKey: monthKey,
    month: month + 1,
    year: year,
    deadline: deadlineStr
  }
}];

// Parse Firebase orders and filter pending ones
const response = $input.first().json;
const prevData = $('Check Deadline').first().json;

if (!response.fields) return [];

function fbVal(v) {
  if (!v) return null;
  if (v.stringValue !== undefined) return v.stringValue;
  if (v.integerValue !== undefined) return parseInt(v.integerValue);
  if (v.nullValue !== undefined) return null;
  if (v.mapValue) {
    const obj = {};
    const f = v.mapValue.fields;
    for (const k in f) obj[k] = fbVal(f[k]);
    return obj;
  }
  return null;
}

const results = [];
['2F', '3F'].forEach(floor => {
  if (!response.fields[floor]) return;
  const order = fbVal(response.fields[floor]);
  if (!order) return;

  // Only send reminder for pending orders
  if (order.status !== 'pending') return;
  if (!order.email) return;

  const budgetKey = floor === '2F' ? '석민이앤씨' : '넷폼알앤디';

  results.push({
    floor: floor,
    team: order.team || '',
    name: order.contact || '',
    email: order.email || '',
    month: prevData.month,
    year: prevData.year,
    monthKey: prevData.monthKey,
    deadline: prevData.deadline,
    budget: '500,000'
  });
});

return results;
